  "law": {
    "id": "NRS-484B-507-1",
    "title": "Stopping, standing or parking in zone for loading freight at curb (1)",
    "text": "A person shall not stop, stand or park a vehicle for any purpose or length of time other than for the expeditious unloading and delivery or pickup and loading of materials in any place marked as a freight curb loading zone during hours when the provisions applicable to such zones are in effect. The driver of a vehicle may stop temporarily at a place marked as a freight curb loading zone for the purpose of and while actually engaged in loading or unloading passengers, when such stopping does not interfere with any motor vehicle used for the transportation of materials which is waiting to enter or about to enter such zone.",
    "source": "NRS 484B.507(1); with 484B.507(2)"
  }
